script.setup:
// animal-proc-anim by argonaut (MIT, https://github.com/argonautcode/animal-proc-anim), ported from
// Processing (Java) to JS: Chain.pde (distance-constrained joints with angle limits, and FABRIK for the
// legs), Util.pde (constrainDistance/constrainAngle/relativeAngleDiff/simplifyAngle), Fish.pde, Snake.pde
// and Lizard.pde (resolve + display, same numbers, colours and draw order). Processing's curveVertex
// (Catmull-Rom) is converted to Canvas 2D bezier curves. The original follows the mouse every frame; here
// each animal also wanders on its own by chasing a smoothly steered point, and follows the pointer while
// it's moving or pressed. Drawn with Canvas 2D at screen resolution and composited on ctx.gl with shadows.
const TWO_PI = Math.PI * 2, PI = Math.PI;

// --- Util.pde ---
const V = (x, y) => ({ x, y });
const sub = (a, b) => V(a.x - b.x, a.y - b.y);
const add = (a, b) => V(a.x + b.x, a.y + b.y);
const heading = (v) => Math.atan2(v.y, v.x);
const setMag = (v, m) => { const l = Math.hypot(v.x, v.y); return l > 0 ? V((v.x / l) * m, (v.y / l) * m) : V(0, 0); };
const fromAngle = (a, m) => V(Math.cos(a) * m, Math.sin(a) * m);
const lerpV = (a, b, t) => V(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t);
const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
function constrainDistance(pos, anchor, constraint) { return add(anchor, setMag(sub(pos, anchor), constraint)); }
function simplifyAngle(angle) {
  while (angle >= TWO_PI) angle -= TWO_PI;
  while (angle < 0) angle += TWO_PI;
  return angle;
}
function relativeAngleDiff(angle, anchor) {
  angle = simplifyAngle(angle + PI - anchor);
  return PI - angle;
}
function constrainAngle(angle, anchor, constraint) {
  if (Math.abs(relativeAngleDiff(angle, anchor)) <= constraint) return simplifyAngle(angle);
  if (relativeAngleDiff(angle, anchor) > constraint) return simplifyAngle(anchor - constraint);
  return simplifyAngle(anchor + constraint);
}

// --- Chain.pde ---
class Chain {
  constructor(origin, jointCount, linkSize, angleConstraint = TWO_PI) {
    this.linkSize = linkSize;
    this.angleConstraint = angleConstraint;
    this.joints = [V(origin.x, origin.y)];
    this.angles = [0];
    for (let i = 1; i < jointCount; i++) { this.joints.push(add(this.joints[i - 1], V(0, linkSize))); this.angles.push(0); }
  }
  resolve(pos) {
    const j = this.joints, a = this.angles;
    a[0] = heading(sub(pos, j[0]));
    j[0] = pos;
    for (let i = 1; i < j.length; i++) {
      const cur = heading(sub(j[i - 1], j[i]));
      a[i] = constrainAngle(cur, a[i - 1], this.angleConstraint);
      j[i] = sub(j[i - 1], fromAngle(a[i], this.linkSize));
    }
  }
  fabrikResolve(pos, anchor) {
    const j = this.joints;
    j[0] = pos;
    for (let i = 1; i < j.length; i++) j[i] = constrainDistance(j[i], j[i - 1], this.linkSize);
    j[j.length - 1] = anchor;
    for (let i = j.length - 2; i >= 0; i--) j[i] = constrainDistance(j[i], j[i + 1], this.linkSize);
  }
}

// Processing drawing helpers on a Canvas 2D context
const rgb = (r, g, b) => `rgb(${r},${g},${b})`;
const WHITE = "#fff";
// curveVertex list -> Catmull-Rom through points 1..n-2 (Processing skips the first and last as controls)
function curveShape(g, P, close) {
  g.beginPath();
  g.moveTo(P[1].x, P[1].y);
  for (let i = 1; i < P.length - 2; i++) {
    const p0 = P[i - 1], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2];
    g.bezierCurveTo(p1.x + (p2.x - p0.x) / 6, p1.y + (p2.y - p0.y) / 6, p2.x - (p3.x - p1.x) / 6, p2.y - (p3.y - p1.y) / 6, p2.x, p2.y);
  }
  if (close) g.closePath();
}
function fillStroke(g) { g.fill(); g.stroke(); }
function ellipseAt(g, x, y, rot, w, h) {
  g.beginPath();
  g.ellipse(x, y, w / 2, h / 2, rot, 0, TWO_PI);
  fillStroke(g);
}
function drawChain(g, chain) { // Chain.display (debug skeleton)
  g.lineWidth = 8; g.strokeStyle = WHITE;
  g.beginPath();
  chain.joints.forEach((p, i) => (i ? g.lineTo(p.x, p.y) : g.moveTo(p.x, p.y)));
  g.stroke();
  g.fillStyle = rgb(42, 44, 53);
  for (const p of chain.joints) ellipseAt(g, p.x, p.y, 0, 32, 32);
}

// --- Fish.pde --- "Bloopy lil dude"
class Fish {
  constructor(origin) {
    this.bodyColor = rgb(58, 124, 165); this.finColor = rgb(129, 195, 215);
    this.bodyWidth = [68, 81, 84, 83, 77, 64, 51, 38, 32, 19];
    this.spine = new Chain(origin, 12, 64, PI / 8); // 10 body segments + 2 for the caudal fin
    this.step = 16;
  }
  resolve(target) {
    const head = this.spine.joints[0];
    this.spine.resolve(add(head, setMag(sub(target, head), this.step * this.speed)));
  }
  px(i, ao, lo) { return this.spine.joints[i].x + Math.cos(this.spine.angles[i] + ao) * (this.bodyWidth[i] + lo); }
  py(i, ao, lo) { return this.spine.joints[i].y + Math.sin(this.spine.angles[i] + ao) * (this.bodyWidth[i] + lo); }
  P(i, ao, lo) { return V(this.px(i, ao, lo), this.py(i, ao, lo)); }
  display(g) {
    const j = this.spine.joints, a = this.spine.angles;
    g.lineWidth = 4; g.strokeStyle = WHITE; g.fillStyle = this.finColor;
    const headToMid1 = relativeAngleDiff(a[0], a[6]);
    const headToMid2 = relativeAngleDiff(a[0], a[7]);
    const headToTail = headToMid1 + relativeAngleDiff(a[6], a[11]);
    // pectoral fins
    ellipseAt(g, this.px(3, PI / 3, 0), this.py(3, PI / 3, 0), a[2] - PI / 4, 160, 64);
    ellipseAt(g, this.px(3, -PI / 3, 0), this.py(3, -PI / 3, 0), a[2] + PI / 4, 160, 64);
    // ventral fins
    ellipseAt(g, this.px(7, PI / 2, 0), this.py(7, PI / 2, 0), a[6] - PI / 4, 96, 32);
    ellipseAt(g, this.px(7, -PI / 2, 0), this.py(7, -PI / 2, 0), a[6] + PI / 4, 96, 32);
    // caudal fin
    const C = [];
    for (let i = 8; i < 12; i++) {
      const w = 1.5 * headToTail * (i - 8) * (i - 8);
      C.push(V(j[i].x + Math.cos(a[i] - PI / 2) * w, j[i].y + Math.sin(a[i] - PI / 2) * w));
    }
    for (let i = 11; i >= 8; i--) {
      const w = Math.max(-13, Math.min(13, headToTail * 6));
      C.push(V(j[i].x + Math.cos(a[i] + PI / 2) * w, j[i].y + Math.sin(a[i] + PI / 2) * w));
    }
    curveShape(g, C, true); fillStroke(g);
    // body
    g.fillStyle = this.bodyColor;
    const B = [];
    for (let i = 0; i < 10; i++) B.push(this.P(i, PI / 2, 0));
    B.push(this.P(9, PI, 0));
    for (let i = 9; i >= 0; i--) B.push(this.P(i, -PI / 2, 0));
    B.push(this.P(0, -PI / 6, 0), this.P(0, 0, 4), this.P(0, PI / 6, 0));
    B.push(this.P(0, PI / 2, 0), this.P(1, PI / 2, 0), this.P(2, PI / 2, 0));
    curveShape(g, B, true); fillStroke(g);
    // dorsal fin
    g.fillStyle = this.finColor;
    g.beginPath();
    g.moveTo(j[4].x, j[4].y);
    g.bezierCurveTo(j[5].x, j[5].y, j[6].x, j[6].y, j[7].x, j[7].y);
    g.bezierCurveTo(j[6].x + Math.cos(a[6] + PI / 2) * headToMid2 * 16, j[6].y + Math.sin(a[6] + PI / 2) * headToMid2 * 16,
      j[5].x + Math.cos(a[5] + PI / 2) * headToMid1 * 16, j[5].y + Math.sin(a[5] + PI / 2) * headToMid1 * 16, j[4].x, j[4].y);
    fillStroke(g);
    // eyes
    g.fillStyle = WHITE;
    ellipseAt(g, this.px(0, PI / 2, -18), this.py(0, PI / 2, -18), 0, 24, 24);
    ellipseAt(g, this.px(0, -PI / 2, -18), this.py(0, -PI / 2, -18), 0, 24, 24);
  }
  skeleton(g) { drawChain(g, this.spine); }
}

// --- Snake.pde --- "Wiggly lil dude"
class Snake {
  constructor(origin) { this.spine = new Chain(origin, 48, 64, PI / 8); this.step = 8; }
  resolve(target) {
    const head = this.spine.joints[0];
    this.spine.resolve(add(head, setMag(sub(target, head), this.step * this.speed)));
  }
  bodyWidth(i) { return i === 0 ? 76 : i === 1 ? 80 : 64 - i; }
  P(i, ao, lo) {
    const p = this.spine.joints[i], a = this.spine.angles[i] + ao, w = this.bodyWidth(i) + lo;
    return V(p.x + Math.cos(a) * w, p.y + Math.sin(a) * w);
  }
  display(g) {
    g.lineWidth = 4; g.strokeStyle = WHITE; g.fillStyle = rgb(172, 57, 49);
    const n = this.spine.joints.length, B = [];
    for (let i = 0; i < n; i++) B.push(this.P(i, PI / 2, 0));
    B.push(this.P(47, PI, 0));
    for (let i = n - 1; i >= 0; i--) B.push(this.P(i, -PI / 2, 0));
    B.push(this.P(0, -PI / 6, 0), this.P(0, 0, 0), this.P(0, PI / 6, 0));
    B.push(this.P(0, PI / 2, 0), this.P(1, PI / 2, 0), this.P(2, PI / 2, 0));
    curveShape(g, B, true); fillStroke(g);
    g.fillStyle = WHITE;
    for (const s of [1, -1]) { const e = this.P(0, (s * PI) / 2, -18); ellipseAt(g, e.x, e.y, 0, 24, 24); }
  }
  skeleton(g) { drawChain(g, this.spine); }
}

// --- Lizard.pde --- "Glitchy lil dude"
class Lizard {
  constructor(origin) {
    this.bodyWidth = [52, 58, 40, 60, 68, 71, 65, 50, 28, 15, 11, 9, 7, 7];
    this.spine = new Chain(origin, 14, 64, PI / 8);
    this.arms = []; this.armDesired = [];
    for (let i = 0; i < 4; i++) { this.arms.push(new Chain(origin, 3, i < 2 ? 52 : 36)); this.armDesired.push(V(0, 0)); }
    this.step = 12;
  }
  px(i, ao, lo) { return this.spine.joints[i].x + Math.cos(this.spine.angles[i] + ao) * (this.bodyWidth[i] + lo); }
  py(i, ao, lo) { return this.spine.joints[i].y + Math.sin(this.spine.angles[i] + ao) * (this.bodyWidth[i] + lo); }
  P(i, ao, lo) { return V(this.px(i, ao, lo), this.py(i, ao, lo)); }
  resolve(target) {
    const head = this.spine.joints[0];
    this.spine.resolve(add(head, setMag(sub(target, head), this.step * this.speed)));
    for (let i = 0; i < 4; i++) {
      const side = i % 2 === 0 ? 1 : -1, bodyIndex = i < 2 ? 3 : 7, angle = i < 2 ? PI / 4 : PI / 3;
      const desired = this.P(bodyIndex, angle * side, 80);
      if (dist(desired, this.armDesired[i]) > 200) this.armDesired[i] = desired;
      this.arms[i].fabrikResolve(lerpV(this.arms[i].joints[0], this.armDesired[i], 0.4), this.P(bodyIndex, (PI / 2) * side, -20));
    }
  }
  display(g) {
    g.lineCap = "round";
    for (let i = 0; i < 4; i++) {
      const shoulder = this.arms[i].joints[2], foot = this.arms[i].joints[0];
      let elbow = this.arms[i].joints[1];
      // the original's correction that bends the back legs the right way
      const para = sub(foot, shoulder), perp = setMag(V(-para.y, para.x), 30);
      if (i === 2) elbow = sub(elbow, perp); else if (i === 3) elbow = add(elbow, perp);
      for (const [w, c] of [[40, WHITE], [32, rgb(82, 121, 111)]]) {
        g.lineWidth = w; g.strokeStyle = c;
        g.beginPath(); g.moveTo(shoulder.x, shoulder.y);
        g.bezierCurveTo(elbow.x, elbow.y, elbow.x, elbow.y, foot.x, foot.y);
        g.stroke();
      }
    }
    g.lineCap = "butt";
    g.lineWidth = 4; g.strokeStyle = WHITE; g.fillStyle = rgb(82, 121, 111);
    const n = this.spine.joints.length, B = [];
    for (let i = 0; i < n; i++) B.push(this.P(i, PI / 2, 0));
    for (let i = n - 1; i >= 0; i--) B.push(this.P(i, -PI / 2, 0));
    B.push(V(this.px(0, -PI / 6, -8), this.py(0, -PI / 6, -10)), V(this.px(0, 0, -6), this.py(0, 0, -4)), V(this.px(0, PI / 6, -8), this.py(0, PI / 6, -10)));
    B.push(this.P(0, PI / 2, 0), this.P(1, PI / 2, 0), this.P(2, PI / 2, 0));
    curveShape(g, B, true); fillStroke(g);
    g.fillStyle = WHITE;
    for (const s of [1, -1]) { const e = this.P(0, (s * 3 * PI) / 5, -7); ellipseAt(g, e.x, e.y, 0, 24, 24); }
  }
  skeleton(g) { drawChain(g, this.spine); for (const a of this.arms) drawChain(g, a); }
}

// --- autonomy (new): a steered point ahead of the head stands in for the mouse ---
function makeAnimal(kind, x, y, phase) {
  const A = kind === 0 ? new Fish(V(x, y)) : kind === 1 ? new Snake(V(x, y)) : new Lizard(V(x, y));
  A.kind = kind; A.phase = phase; A.dir = phase * 2.1; A.speed = 1; A.t = phase * 37;
  return A;
}
// world goal wandering slowly over the visible area
function goal(A, t, w, h) {
  const p = A.phase * 11.3;
  const nx = 0.6 * Math.sin(t * 0.21 + p) + 0.4 * Math.sin(t * 0.47 + p * 2.7);
  const ny = 0.6 * Math.sin(t * 0.17 + p * 1.9) + 0.4 * Math.sin(t * 0.39 + p * 0.6);
  return V(w * (0.5 + 0.3 * nx), h * (0.5 + 0.28 * ny));
}
function wanderTarget(A, w, h, dt, others = []) {
  A.t += dt;
  const head = A.spine.joints[0];
  let gp = goal(A, A.t, w, h);
  // with company, keep a little personal space: push the goal away from nearby heads
  for (const B of others) {
    const d = sub(head, B.spine.joints[0]), l = Math.hypot(d.x, d.y);
    if (l > 1 && l < 900) gp = add(gp, setMag(d, 1100 * (1 - l / 900)));
  }
  // near the edge of the view, head back towards the middle so nobody wanders off
  const m = Math.min(w, h) * 0.2;
  const out = Math.min(1, Math.max(0, m - head.x, head.x - (w - m), m - head.y, head.y - (h - m)) / m);
  const want = heading(sub(out > 0 ? lerpV(gp, V(w / 2, h / 2), out) : gp, head));
  const turn = relativeAngleDiff(want, A.dir); // > 0 means turn towards smaller angles
  const rate = [2.0, 0.95, 2.4][A.kind] * (0.75 + 0.25 * Math.sin(A.t * 0.9 + A.phase * 5)) * (1 + 1.5 * out);
  A.dir -= Math.max(-rate * dt, Math.min(rate * dt, turn));
  // a gentle sway so straight runs aren't ruler-straight
  const sway = 0.35 * Math.sin(A.t * [1.7, 2.6, 1.3][A.kind] + A.phase);
  return add(head, fromAngle(A.dir + sway * 0.4, 300));
}

const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_layer;
uniform vec2 u_resolution;
uniform vec3 u_bgColor;
uniform float u_shadowPx, u_time;
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
void main() {
  vec2 uv = v_uv;
  vec3 bg = u_bgColor;
  float r = length((uv - vec2(0.5, 0.55)) * vec2(u_resolution.x / u_resolution.y, 1.0));
  bg *= 1.18 - 0.42 * smoothstep(0.0, 1.1, r);
  bg += (hash(floor(uv * u_resolution) + fract(u_time) * 17.0) - 0.5) * 0.012;
  vec2 off = vec2(0.35, -0.6) * u_shadowPx / u_resolution;
  float lod = log2(max(u_shadowPx, 1.0));
  float sh = textureLod(u_layer, uv - off, lod).a;
  bg *= 1.0 - 0.55 * sh;
  vec4 c = texture(u_layer, uv);
  outColor = vec4(bg * (1.0 - c.a) + c.rgb, 1.0);
}`;

const gl = ctx.gl;
const tex = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, tex);
for (const [k, v] of [[gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR], [gl.TEXTURE_MAG_FILTER, gl.LINEAR], [gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, k, v);

Object.assign(ctx.state, {
  makeAnimal, wanderTarget, tex, cv: null, g: null, animals: null, kind: -1, acc: 0, lastMove: -99, W: 0, H: 0,
  prog: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs),
});

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const [W, H] = ctx.resolution;
const STEP = 1 / 60; // the original resolves once per frame at 60 fps

// world units: the original's pixels; the shorter screen side shows VIEW of them
const kind = Math.max(0, Math.min(3, u.u_creature | 0));
const VIEW = [1100, 1700, 1150, 2100][kind] / u.u_size;
const scale = Math.min(W, H) / VIEW;
const ww = W / scale, wh = H / scale;

// offscreen 2D layer at screen resolution (capped), recreated on resize
const cap = Math.min(1, 2560 / Math.max(W, H));
if (!s.cv || ctx.resized || s.W !== W || s.H !== H) {
  s.W = W; s.H = H;
  s.cv = new OffscreenCanvas(Math.max(1, Math.round(W * cap)), Math.max(1, Math.round(H * cap)));
  s.g = s.cv.getContext("2d");
}

function spawn() {
  const kinds = kind === 3 ? [1, 2, 0] : [kind];
  s.animals = kinds.map((k, i) => s.makeAnimal(k, ww * (0.3 + 0.2 * i), wh * (0.5 + 0.1 * (i - 1)), i * 0.37 + 0.2));
  // let them swim a few seconds before the first frame, so bodies start curved and in motion
  for (let n = 0; n < 900; n++) for (const A of s.animals) { A.speed = Math.max(0.6, u.u_speed); A.resolve(s.wanderTarget(A, ww, wh, STEP, s.animals.filter((B) => B !== A))); }
}
if (kind !== s.kind || !s.animals) { s.kind = kind; spawn(); }

// pointer: follow it while it moves or is pressed (as the original always does), else wander
const m = ctx.mouse, mp = ctx.mousePrev;
if (ctx.frame > 2 && (ctx.mouseDown || Math.abs(m[0] - mp[0]) + Math.abs(m[1] - mp[1]) > 1e-4)) s.lastMove = ctx.time;
const following = u.u_follow && (ctx.mouseDown || ctx.time - s.lastMove < 2.5) && m[0] > 0 && m[1] > 0;
const mouseW = { x: m[0] * ww, y: m[1] * wh };

s.acc = Math.min(s.acc + Math.min(ctx.dt, 0.1), 4 * STEP);
while (s.acc >= STEP) {
  s.acc -= STEP;
  s.animals.forEach((A, i) => {
    A.speed = u.u_speed;
    let target = s.wanderTarget(A, ww, wh, STEP, s.animals.filter((B) => B !== A));
    if (following) {
      // several animals: each keeps a little distance around the pointer instead of piling up
      const o = s.animals.length > 1 ? { x: Math.cos(i * 2.1 + ctx.time * 0.5) * 220, y: Math.sin(i * 2.1 + ctx.time * 0.5) * 220 } : { x: 0, y: 0 };
      target = { x: mouseW.x + o.x, y: mouseW.y + o.y };
      A.dir = A.spine.angles[0];
    }
    A.resolve(target);
  });
}

const g = s.g, k = scale * cap;
g.setTransform(1, 0, 0, 1, 0, 0);
g.clearRect(0, 0, s.cv.width, s.cv.height);
g.setTransform(k, 0, 0, k, 0, 0);
g.lineJoin = "round";
for (const A of s.animals) A.display(g);
if (u.u_skeleton) {
  g.globalAlpha = 0.85;
  for (const A of s.animals) A.skeleton(g);
  g.globalAlpha = 1;
}

gl.bindTexture(gl.TEXTURE_2D, s.tex);
gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.cv);
gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
gl.generateMipmap(gl.TEXTURE_2D);

ctx.publish("mode", following ? "following you" : "wandering");
ctx.publish("joints", s.animals.reduce((n, A) => n + A.spine.joints.length + (A.arms ? 12 : 0), 0));

gl.useProgram(s.prog);
ctx.utils.setUniforms(s.prog, { u_resolution: [W, H], u_bgColor: u.u_background, u_shadowPx: 34 * scale, u_time: ctx.time });
ctx.utils.bindTexture(s.prog, "u_layer", s.tex, 0);
ctx.utils.drawFullscreen(s.prog);
